    it.each([
      ['2026-02-30', '2026-03-31'],
      ['2025-02-29', '2025-03-31'],
      ['2026-13-01', '2026-12-31'],
      ['2026-00-10', '2026-12-31'],
      ['2026-1-01', '2026-12-31'],
      ['2026-01-01T00:00', '2026-12-31'],
