import { badRequest } from '@/lib/http'
import { parseGatewayPaidAt } from '@/lib/myt'

/**
 * application/x-www-form-urlencoded body -> fields. Returns null when a key repeats:
 * the signature source would be ambiguous, so such a request cannot be verified.
 */
export function parseFormFields(raw: string): Record<string, string> | null {
  const fields: Record<string, string> = {}
  for (const [key, value] of new URLSearchParams(raw)) {
    if (Object.hasOwn(fields, key)) return null
    fields[key] = value
  }
  return fields
}

export interface ParsedCallback {
  billId: string
  paid: boolean
  paidAmountSen: bigint
  paidAt: Date | null
  transactionId: string
}

/** Validates a callback whose signature has already been verified. Error messages never echo values. */
export function parseCallback(fields: Record<string, string>): ParsedCallback {
  const billId = fields.id
  if (!billId) throw badRequest('id is required')
  if (fields.paid !== 'true' && fields.paid !== 'false') throw badRequest('paid must be true or false')
  const paid = fields.paid === 'true'
  const amount = fields.paid_amount ?? (paid ? undefined : '0')
  if (amount === undefined || !/^\d{1,15}$/.test(amount)) throw badRequest('paid_amount must be an integer in sen')
  let paidAt: Date | null = null
  if (paid) {
    try {
      paidAt = parseGatewayPaidAt(fields.paid_at ?? '')
    } catch {
      throw badRequest('paid_at must look like 2026-04-01 00:30:12 +0800')
    }
  }
  return { billId, paid, paidAmountSen: BigInt(amount), paidAt, transactionId: fields.transaction_id ?? '' }
}
EOF
cat > src/lib/gateway/callback.test.ts <<'EOF'
import { describe, expect, it } from 'vitest'
import { DomainError } from '@/lib/http'
import { parseCallback, parseFormFields } from './callback'

describe('parseFormFields', () => {
  it('decodes form encoding, including spaces and +', () => {
    expect(parseFormFields('id=bill_1&paid_at=2026-04-01+00%3A30%3A12+%2B0800&extra=a%7Cb')).toEqual({
      id: 'bill_1',
      paid_at: '2026-04-01 00:30:12 +0800',
      extra: 'a|b',
    })
  })

  it('refuses repeated keys', () => {
    expect(parseFormFields('id=bill_1&paid=true&paid=false')).toBeNull()
  })
})

describe('parseCallback', () => {
  const paid = { id: 'bill_1', paid: 'true', paid_amount: '210050', paid_at: '2026-04-01 00:30:12 +0800', transaction_id: 'TX-1' }

  it('parses a paid callback; received_at will be paid_at', () => {
    expect(parseCallback(paid)).toEqual({
      billId: 'bill_1',
      paid: true,
      paidAmountSen: 210050n,
      paidAt: new Date('2026-03-31T16:30:12.000Z'),
      transactionId: 'TX-1',
    })
  })

  it('does not need paid_at when not paid', () => {
    expect(parseCallback({ id: 'bill_1', paid: 'false', paid_amount: '0' }).paidAt).toBeNull()
  })

  it.each([
    [{ ...paid, id: '' }],
    [{ ...paid, paid: 'yes' }],
    [{ ...paid, paid_amount: '2100.50' }],
    [{ ...paid, paid_amount: '-1' }],
    [{ ...paid, paid_at: '2026-04-01T00:30:12+08:00' }],
  ])('rejects %j with a 400', (fields) => {
    expect(() => parseCallback(fields)).toThrow(DomainError)
  })
})
EOF
