                            {isManager ? (
                              <PaymentActions
                                paymentId={payment.id}
                                status={payment.status}
                                summary={`${PAYMENT_METHOD_LABEL[payment.method].toLowerCase()} payment received ${formatMalaysia(new Date(payment.receivedAt))}`}
