        </Button>
      ))}
      {open && (
        <ConfirmDialog
          key={open}
          action={open}
          paymentId={paymentId}
          summary={summary}
          amountSen={amountSen}
          onClose={() => setOpen(null)}
        />
      )}
    </div>
  )
}

function ConfirmDialog({
  action,
  paymentId,
  summary,
  amountSen,
  onClose,
}: {
  action: Action
  paymentId: string
  summary: string
  amountSen: number
  onClose: () => void
}) {
