const newBlock = `  // Bumping the version re-reads everything; the previous data stays on screen meanwhile.
  const [version, setVersion] = useState(0)
  const reload = useCallback(() => setVersion((v) => v + 1), [])

  useEffect(() => {
    let cancelled = false
    const now = new Date()
    loadPortal(now, todayInMalaysia(now)).then(
      (data) => {
        if (!cancelled) setState({ kind: 'ready', data })
      },
      (error: unknown) => {
        if (!cancelled) setState({ kind: 'error', message: error instanceof Error ? error.message : 'Could not load your tenancy.' })
      },
    )
    return () => {
      cancelled = true
    }
  }, [version])

`
s = s.replace(oldBlock, newBlock)
s = s.replace("onClick={() => void reload()}", "onClick={reload}")
s = s.split('onChanged: () => Promise<void>').join('onChanged: () => void')
s = s.split('onSaved: () => Promise<void>').join('onSaved: () => void')
s = s.replace('      await onChanged()', '      onChanged()').replace('      await onSaved()', '      onSaved()')
fs.writeFileSync(f, s)
EOF
npm run typecheck 2>&1 | tail -3 && npx eslint src 2>&1 | tail -10 && echo LINT_DONE

