import type { InvoiceKind } from '@/lib/billing'
import type { Tx } from '@/lib/db/prisma'
import { dateColumnToString } from '@/lib/myt'

// Allocation order (brief section 4): due date, then deposit before rent, then period index.
// Also the order GET /api/leases/:leaseId returns invoices in.
export interface OrderedInvoice {
  kind: InvoiceKind
  dueDate: string // 'YYYY-MM-DD'
  periodIndex: number | null
}

export function compareAllocationOrder(a: OrderedInvoice, b: OrderedInvoice): number {
  if (a.dueDate !== b.dueDate) return a.dueDate < b.dueDate ? -1 : 1
  if (a.kind !== b.kind) return a.kind === 'deposit' ? -1 : 1
  return (a.periodIndex ?? -1) - (b.periodIndex ?? -1)
}

export interface AllocatableInvoice extends OrderedInvoice {
  id: string
  amountSen: bigint
  paidSen: bigint
}

export interface AllocationPlan {
  allocations: { invoiceId: string; amountSen: bigint }[]
  unappliedSen: bigint
}

/**
 * Pure: fills each invoice up to its unpaid amount in allocation order, including
 * invoices not due yet. Whatever is left once every invoice is paid is unapplied.
 */
export function planAllocation(invoices: AllocatableInvoice[], amountSen: bigint): AllocationPlan {
  if (amountSen < 0n) throw new Error('amountSen must not be negative')
  let remaining = amountSen
  const allocations: AllocationPlan['allocations'] = []
  for (const invoice of [...invoices].sort(compareAllocationOrder)) {
    if (remaining === 0n) break
    const unpaid = invoice.amountSen - invoice.paidSen
    if (unpaid <= 0n) continue
    const portion = unpaid < remaining ? unpaid : remaining
    allocations.push({ invoiceId: invoice.id, amountSen: portion })
    remaining -= portion
  }
  return { allocations, unappliedSen: remaining }
}

/**
 * Allocates an approved payment to its lease's invoices and stores the remainder as
 * unapplied_sen. The caller must hold the lease row lock (lockLease) in this transaction,
 * which is what makes the paid amounts read here stable.
 */
export async function allocate(tx: Tx, paymentId: string): Promise<AllocationPlan> {
  const payment = await tx.payments.findUniqueOrThrow({
    where: { id: paymentId },
    select: { id: true, org_id: true, lease_id: true, amount_sen: true, status: true },
  })
  if (payment.status !== 'approved') throw new Error(`Cannot allocate a ${payment.status} payment`)
  const existing = await tx.payment_allocations.count({ where: { payment_id: paymentId } })
  if (existing > 0) throw new Error('Payment is already allocated')

  const invoices = await tx.invoices.findMany({
    where: { lease_id: payment.lease_id },
    include: { payment_allocations: { select: { amount_sen: true } } },
  })
  const plan = planAllocation(
    invoices.map((invoice) => ({
      id: invoice.id,
      kind: invoice.kind,
      dueDate: dateColumnToString(invoice.due_date),
      periodIndex: invoice.period_index,
      amountSen: invoice.amount_sen,
      paidSen: invoice.payment_allocations.reduce((sum, a) => sum + a.amount_sen, 0n),
    })),
    payment.amount_sen,
  )

  if (plan.allocations.length > 0) {
    await tx.payment_allocations.createMany({
      data: plan.allocations.map((allocation) => ({
        org_id: payment.org_id,
        payment_id: payment.id,
        invoice_id: allocation.invoiceId,
        amount_sen: allocation.amountSen,
      })),
    })
  }
  await tx.payments.update({ where: { id: payment.id }, data: { unapplied_sen: plan.unappliedSen } })
  return plan
}

import { describe, expect, it } from 'vitest'
import { planAllocation, type AllocatableInvoice } from './allocation'

const inv = (
  id: string,
  kind: 'deposit' | 'rent',
  dueDate: string,
  periodIndex: number | null,
  amountSen: bigint,
  paidSen = 0n,
): AllocatableInvoice => ({ id, kind, dueDate, periodIndex, amountSen, paidSen })

// Aisyah's schedule (brief section 3).
const aisyah = [
  inv('r5', 'rent', '2026-06-30', 5, 77419n),
  inv('r1', 'rent', '2026-02-28', 1, 150000n),
  inv('r0', 'rent', '2026-01-31', 0, 150000n),
  inv('dep', 'deposit', '2026-01-31', null, 300000n),
  inv('r2', 'rent', '2026-03-31', 2, 150000n),
  inv('r3', 'rent', '2026-04-30', 3, 150000n),
  inv('r4', 'rent', '2026-05-31', 4, 150000n),
]

describe('planAllocation', () => {
  it('fills the deposit before rent due the same day (seed cash RM 3,000)', () => {
    expect(planAllocation(aisyah, 300000n)).toEqual({
      allocations: [{ invoiceId: 'dep', amountSen: 300000n }],
      unappliedSen: 0n,
    })
  })

  it('then fills period 0 and part of period 1 (seed transfer RM 2,000)', () => {
    const afterCash = aisyah.map((i) => (i.id === 'dep' ? { ...i, paidSen: 300000n } : i))
    expect(planAllocation(afterCash, 200000n)).toEqual({
      allocations: [
        { invoiceId: 'r0', amountSen: 150000n },
        { invoiceId: 'r1', amountSen: 50000n },
      ],
      unappliedSen: 0n,
    })
  })

  it('tops up a partially paid invoice and skips paid ones', () => {
    const invoices = [inv('a', 'rent', '2026-01-01', 0, 1000n, 1000n), inv('b', 'rent', '2026-02-01', 1, 1000n, 400n), inv('c', 'rent', '2026-03-01', 2, 1000n)]
    expect(planAllocation(invoices, 900n).allocations).toEqual([
      { invoiceId: 'b', amountSen: 600n },
      { invoiceId: 'c', amountSen: 300n },
    ])
  })

  it('pays invoices that are not due yet and leaves the rest unapplied', () => {
    const invoices = [inv('a', 'rent', '2099-01-01', 0, 1000n), inv('b', 'rent', '2099-02-01', 1, 1000n)]
    expect(planAllocation(invoices, 2500n)).toEqual({
      allocations: [
        { invoiceId: 'a', amountSen: 1000n },
        { invoiceId: 'b', amountSen: 1000n },
      ],
      unappliedSen: 500n,
    })
  })

  it('skips zero-sen invoices', () => {
    const invoices = [inv('zero', 'rent', '2026-01-01', 0, 0n), inv('b', 'rent', '2026-02-01', 1, 100n)]
    expect(planAllocation(invoices, 100n).allocations).toEqual([{ invoiceId: 'b', amountSen: 100n }])
  })

  it('orders by due date before kind (a later deposit comes after earlier rent)', () => {
    const invoices = [inv('dep', 'deposit', '2026-02-01', null, 100n), inv('r0', 'rent', '2026-01-01', 0, 100n)]
    expect(planAllocation(invoices, 150n).allocations.map((a) => a.invoiceId)).toEqual(['r0', 'dep'])
  })

  it('does not mutate its input', () => {
    const invoices = [...aisyah]
    planAllocation(invoices, 1n)
    expect(invoices.map((i) => i.id)).toEqual(aisyah.map((i) => i.id))
  })

  it('allocates nothing when there is nothing unpaid', () => {
    expect(planAllocation([inv('a', 'rent', '2026-01-01', 0, 100n, 100n)], 50n)).toEqual({ allocations: [], unappliedSen: 50n })
  })
})

import { randomBytes } from 'node:crypto'
import { canSee, type Caller } from '@/lib/auth/getCaller'
import { prisma } from '@/lib/db/prisma'
import { forbidden, notFound, unprocessable } from '@/lib/http'
import { dateColumnToString, todayInMalaysia } from '@/lib/myt'
import { allocate } from '@/services/allocation'
import { writeAudit } from '@/services/audit'
import { lockLease } from '@/services/payments'

/** 'bill_' + 128 random bits: impossible to guess, unlike the brief's 'bill_8f3a2c'. */
function newBillId(): string {
  return `bill_${randomBytes(16).toString('hex')}`
}

/**
 * POST /api/leases/:leaseId/gateway-bills (the lease's tenant). The bill is for the amount
 * due now: the unpaid amounts of the lease's invoices due on or before today's Malaysia date.
 */
export async function createGatewayBill(
  caller: Caller,
  leaseId: string,
  now: Date = new Date(),
): Promise<{ billId: string; amountSen: number }> {
  const lease = await prisma.leases.findUnique({ where: { id: leaseId }, select: { id: true, org_id: true, tenant_id: true } })
  if (!lease || !canSee(caller, lease)) throw notFound('Lease not found')
  if (caller.kind !== 'tenant') throw forbidden('Only the tenant can pay online')

  const today = todayInMalaysia(now)
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, lease.id) // read the paid amounts while no payment can change them
    const invoices = await tx.invoices.findMany({
      where: { lease_id: lease.id },
      include: { payment_allocations: { select: { amount_sen: true } } },
    })
    const dueNowSen = invoices
      .filter((invoice) => dateColumnToString(invoice.due_date) <= today)
      .reduce((total, invoice) => {
        const unpaid = invoice.amount_sen - invoice.payment_allocations.reduce((sum, a) => sum + a.amount_sen, 0n)
        return unpaid > 0n ? total + unpaid : total
      }, 0n)
    if (dueNowSen <= 0n) throw unprocessable('Nothing is due on this lease')

    const bill = await tx.gateway_bills.create({
      data: { id: newBillId(), org_id: lease.org_id, lease_id: lease.id, amount_sen: dueNowSen, created_by: caller.userId },
      select: { id: true, amount_sen: true },
    })
    return { billId: bill.id, amountSen: Number(bill.amount_sen) }
  })
}

export interface GatewayCallback {
  billId: string
  paid: boolean
  paidAmountSen: bigint
  paidAt: Date | null // required when paid
  transactionId: string
}

export type WebhookOutcome = 'settled' | 'failed' | 'unchanged'

/**
 * Applies a verified gateway callback (brief section 5 table). Throws notFound for an
 * unknown bill and unprocessable for a paid amount that is not the bill's amount.
 *
 * Concurrency: the lease row and then the bill row are locked, and the bill's status is
 * re-read under the lock, so of two identical deliveries arriving together the second
 * sees 'paid' and changes nothing. payments.gateway_bill_id is UNIQUE as a backstop:
 * a bill creates at most one payment, ever.
 */
export async function applyGatewayCallback(callback: GatewayCallback): Promise<WebhookOutcome> {
  const bill = await prisma.gateway_bills.findUnique({
    where: { id: callback.billId },
    select: { id: true, org_id: true, lease_id: true, amount_sen: true },
  })
  if (!bill) throw notFound('Unknown bill')
  if (callback.paid && callback.paidAmountSen !== bill.amount_sen) {
    throw unprocessable("paid_amount is not the bill's amount")
  }

  return prisma.$transaction(async (tx) => {
    await lockLease(tx, bill.lease_id) // lease_id never changes, so reading it unlocked is safe
    const [locked] = await tx.$queryRaw<{ status: 'pending' | 'paid' | 'failed' }[]>`
      SELECT status FROM gateway_bills WHERE id = ${bill.id} FOR UPDATE`

    if (!callback.paid) {
      if (locked.status !== 'pending') return 'unchanged' // failed stays failed; a paid bill never goes back
      await tx.gateway_bills.update({ where: { id: bill.id }, data: { status: 'failed', transaction_id: callback.transactionId, updated_at: new Date() } })
      return 'failed'
    }

    if (locked.status === 'paid') return 'unchanged' // repeat delivery
    const paidAt = callback.paidAt
    if (!paidAt) throw new Error('paid_at is required for a paid callback')
    await tx.gateway_bills.update({
      where: { id: bill.id },
      data: { status: 'paid', paid_at: paidAt, transaction_id: callback.transactionId, updated_at: new Date() },
    })
    const payment = await tx.payments.create({
      data: {
        org_id: bill.org_id,
        lease_id: bill.lease_id,
        amount_sen: bill.amount_sen,
        method: 'online',
        status: 'approved',
        received_at: paidAt,
        gateway_bill_id: bill.id,
      },
      select: { id: true },
    })
    const plan = await allocate(tx, payment.id)
    await writeAudit(tx, {
      orgId: bill.org_id,
      actorId: null,
      action: 'payment.approved',
      entityId: payment.id,
      details: {
        source: 'gateway',
        billId: bill.id,
        leaseId: bill.lease_id,
        amountSen: Number(bill.amount_sen),
        unappliedSen: Number(plan.unappliedSen),
        transactionId: callback.transactionId,
      },
    })
    return 'settled'
  })
}

